#!/usr/bin/env python3
"""Readability + structure edits for Aladdin_Studio_With_AI.html. Body-only; <head> untouched."""
import re, sys

B = "/tmp/claude-0/-home-user-ai-game/44510f87-22a4-5476-9273-389e23c654a8/scratchpad"
SRC = B + "/gtm/out/Aladdin_Studio_With_AI.before_readability.html"
DST = B + "/gtm/out/Aladdin_Studio_With_AI.html"

html = open(SRC, encoding="utf-8").read()
head, body = html.split("</head>", 1)
n_edits = 0

def R(old, new, count=1):
    global body, n_edits
    c = body.count(old)
    if c != count:
        print("MISMATCH (%d found, %d expected):\n  %s" % (c, count, old[:160]))
        sys.exit(1)
    body = body.replace(old, new)
    n_edits += 1

S = lambda n: '<sup class="fnref"><a href="#s%d">%d</a></sup>' % (n, n)

