  '<tr><td class="first">Databricks</td><td>Managed MCP servers, documented</td><td><a href="https://docs.databricks.com/aws/en/generative-ai/mcp/managed-mcp">Databricks documentation</a><sup class="fnref"><a href="#s69">69</a></sup></td></tr>\n'
